"use client";

import { useEffect, useMemo, useState, type ReactElement } from "react";

import { DocumentStatsPanel } from "@rhs-ui/application/document-stats-popover/panel";
import {
  DEFAULT_LABELS,
  IDLE_ABOVE,
  NO_STATS,
  countInIdle,
  countText,
  fill,
  isOne,
  numberText,
  type DocumentGoal,
  type DocumentStats,
  type DocumentStatsLabels,
} from "@rhs-ui/application/document-stats-popover/stats";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { AS_CHILD } from "@rhs-ui/primitives/render-prop";
import { cn } from "@/lib/utils";

export type { DocumentGoal, DocumentStats, DocumentStatsLabels } from "@rhs-ui/application/document-stats-popover/stats";
export { DocumentStatsPanel, type DocumentStatsPanelProps } from "@rhs-ui/application/document-stats-popover/panel";

export interface DocumentStatsPopoverProps {
  /** The whole text of the document, as plain text. */
  text: string;
  /** The text that is selected right now, if any. While it holds something the button and the panel show its numbers and say so. */
  selectionText?: string;
  /** The language the text is in, for where words and sentences end, and for the numbers. Default "en-US". */
  locale?: string;
  /** How many words a person reads in a minute. Default 238. */
  wordsPerMinute?: number;
  /** How many words a person says in a minute. Default 130. */
  speakingWordsPerMinute?: number;
  /** A goal for the document: the panel adds a bar and "Goal: 800 words, 388 to go". */
  goal?: DocumentGoal;
  /** Your own button. The popover then does not draw the word count on it; the count is announced all the same. Default: a small quiet button with the count. */
  trigger?: ReactElement;
  /** Whether the popover is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The side of the button the panel opens on. Default "top", for a button in a footer. */
  side?: "top" | "right" | "bottom" | "left";
  /** How the panel lines up with the button along that side. Default "start". */
  align?: "start" | "center" | "end";
  /** The words the popover says, for translation. */
  labels?: DocumentStatsLabels;
  /** Classes for the default button. */
  className?: string;
}

/** The numbers of a text. Short texts are counted while rendering; a long one is counted in idle time, and until the first count is done there are no numbers. */
function useCount(text: string, locale: string): { stats: DocumentStats | null; counting: boolean } {
  const long = text.length > IDLE_ABOVE;
  const quick = useMemo(() => (long ? NO_STATS : countText(text, locale)), [text, locale, long]);
  const [slow, setSlow] = useState<DocumentStats | null>(null);
  const [counting, setCounting] = useState(false);

  useEffect(() => {
    if (!long) {
      setCounting(false);
      return;
    }
    setCounting(true);
    // Counting restarts at every change, and the one before is cancelled: while keys are being pressed, nothing is counted at all.
    return countInIdle(text, locale, (done) => {
      setSlow(done);
      setCounting(false);
    });
  }, [text, locale, long]);

  return long ? { stats: slow, counting } : { stats: quick, counting: false };
}

/**
 * The word count in an editor's footer, and what is behind it. The button reads "412 words" (or "36 of 412 words" while
 * something is selected) and opens a panel with words, characters with and without spaces, sentences, paragraphs and the
 * time to read and to say it aloud, for the document or for the selection, labelled with which. A goal adds a bar and
 * "Goal: 800 words, 388 to go". Words and sentences are counted by the rules of the locale, a long text is counted in
 * idle time so typing never stalls, and a screen reader hears the new count only once typing pauses, not on every key.
 */
export function DocumentStatsPopover({
  text,
  selectionText = "",
  locale = "en-US",
  wordsPerMinute,
  speakingWordsPerMinute,
  goal,
  trigger,
  open,
  defaultOpen,
  onOpenChange,
  side = "top",
  align = "start",
  labels,
  className,
}: DocumentStatsPopoverProps) {
  const words: Required<DocumentStatsLabels> = { ...DEFAULT_LABELS, ...labels };
  const whole = useCount(text, locale);
  const hasSelection = /\S/.test(selectionText);
  const selection = useCount(hasSelection ? selectionText : "", locale);

  const total = whole.stats?.words ?? 0;
  const count = (value: number) => fill(isOne(value, locale) ? words.wordsOne : words.wordsOther, { count: numberText(value, locale) });
  // What the button says: the count, or while something is selected how much of it that is.
  const summary = !whole.stats
    ? words.counting
    : hasSelection && selection.stats
      ? fill(words.selectionOf, { selection: numberText(selection.stats.words, locale), total: numberText(total, locale) })
      : count(total);

  // A screen reader hears the count once typing has paused, not at every key: the live region only changes after a quiet second.
  const [announced, setAnnounced] = useState(summary);
  useEffect(() => {
    const timer = window.setTimeout(() => setAnnounced(summary), 1000);
    return () => window.clearTimeout(timer);
  }, [summary]);

  return (
    <>
      <Popover open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
        <PopoverTrigger {...AS_CHILD}>
          {trigger ?? (
            <button
              type="button"
              data-slot="document-stats-trigger"
              className={cn(
                "inline-flex h-7 items-center rounded-md px-2 text-xs font-medium whitespace-nowrap text-muted-foreground tabular-nums outline-none",
                "transition-[background-color,color] duration-150 motion-reduce:transition-none",
                "hover:bg-muted hover:text-foreground data-[state=open]:bg-muted data-[state=open]:text-foreground",
                "focus-visible:ring-[3px] focus-visible:ring-ring/40 pointer-coarse:h-9",
                className,
              )}
            >
              {summary}
            </button>
          )}
        </PopoverTrigger>
        <PopoverContent
          data-slot="document-stats-popover"
          side={side}
          align={align}
          sideOffset={8}
          collisionPadding={12}
          aria-label={words.title}
          // Never taller than the room there is: on a small screen the panel scrolls inside itself instead of running off the edge.
          className="relative w-72 max-w-[min(18rem,var(--radix-popover-content-available-width))] max-h-(--radix-popover-content-available-height) overflow-x-hidden overflow-y-auto overscroll-contain p-0 [scrollbar-color:color-mix(in_oklab,var(--foreground)_28%,transparent)_transparent] [scrollbar-width:thin]"
        >
          <DocumentStatsPanel
            stats={whole.stats ?? NO_STATS}
            selection={hasSelection ? (selection.stats ?? NO_STATS) : null}
            goal={goal}
            wordsPerMinute={wordsPerMinute}
            speakingWordsPerMinute={speakingWordsPerMinute}
            counting={whole.counting || (hasSelection && selection.counting)}
            locale={locale}
            labels={labels}
          />
        </PopoverContent>
      </Popover>
      <span role="status" aria-live="polite" className="sr-only">
        {announced}
      </span>
    </>
  );
}

import type { ComponentProps, ReactNode } from "react";

import { IconCheck, IconCursor, IconFileText, IconSpinner } from "@rhs-ui/icons";
import {
  DEFAULT_LABELS,
  durationText,
  fill,
  minutesFor,
  numberText,
  isOne,
  type DocumentGoal,
  type DocumentStats,
  type DocumentStatsLabels,
} from "@rhs-ui/application/document-stats-popover/stats";
import { Badge } from "@rhs-ui/primitives/badge";
import { Progress } from "@rhs-ui/primitives/progress";
import { cn } from "@/lib/utils";

export interface DocumentStatsPanelProps extends Omit<ComponentProps<"div">, "title" | "children"> {
  /** The numbers of the whole document. Count a text with `countText` from the item's `stats` file, or with your editor. */
  stats: DocumentStats;
  /** The numbers of the selection. While it is set the panel shows these, says so, and keeps the whole document in a line beneath. */
  selection?: DocumentStats | null;
  /** A goal for the document: a bar and a sentence, "Goal: 800 words, 388 to go". The goal is always about the whole document. */
  goal?: DocumentGoal;
  /** How many words a person reads in a minute. Default 238. */
  wordsPerMinute?: number;
  /** How many words a person says in a minute. Default 130. */
  speakingWordsPerMinute?: number;
  /** A long text is still being counted: the panel says so and keeps the numbers it has. */
  counting?: boolean;
  /** The language of the numbers and of the times. Default "en-US". */
  locale?: string;
  /** The words the panel says, for translation. */
  labels?: DocumentStatsLabels;
}

function Row({ term, children }: { term: string; children: ReactNode }) {
  return (
    <div className="flex items-baseline justify-between gap-4 py-1.5">
      <dt className="text-muted-foreground">{term}</dt>
      <dd className="font-medium tabular-nums">{children}</dd>
    </div>
  );
}

/**
 * The numbers of a text as the content of a card: the words large, with a tag that says whether they are for the
 * document or for the selection, then characters with and without spaces, sentences, paragraphs, and the time to read it
 * and to say it aloud. A goal adds a bar and one sentence. Figures use tabular numerals, so they do not shift as they
 * change. It is what DocumentStatsPopover shows, usable by itself in a sidebar or a status bar.
 */
export function DocumentStatsPanel({
  stats,
  selection,
  goal,
  wordsPerMinute = 238,
  speakingWordsPerMinute = 130,
  counting = false,
  locale = "en-US",
  labels,
  className,
  ...props
}: DocumentStatsPanelProps) {
  const words: Required<DocumentStatsLabels> = { ...DEFAULT_LABELS, ...labels };
  const shown = selection ?? stats;
  const n = (value: number) => numberText(value, locale);

  // A goal of nothing is no goal: there is nothing to go towards.
  const target = goal && goal.words > 0 ? goal : null;
  const rest = target ? target.words - stats.words : 0;
  const percent = target ? Math.min(100, Math.round((stats.words / target.words) * 100)) : 0;
  const goalText = !target
    ? ""
    : rest > 0
      ? fill(words.goalToGo, { goal: n(target.words), rest: n(rest) })
      : rest === 0
        ? fill(words.goalReached, { goal: n(target.words) })
        : fill(words.goalPassed, { goal: n(target.words), extra: n(-rest) });

  return (
    <div data-slot="document-stats-panel" data-scope={selection ? "selection" : "document"} aria-busy={counting || undefined} className={cn("grid gap-4 p-4 text-sm text-popover-foreground", className)} {...props}>
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          {selection ? (
            <Badge>
              <IconCursor />
              {words.selection}
            </Badge>
          ) : (
            <Badge variant="muted">
              <IconFileText />
              {words.document}
            </Badge>
          )}
          <p className="mt-2.5 flex items-baseline gap-1.5">
            <span className="text-3xl leading-none font-semibold tracking-[-0.03em] tabular-nums">{n(shown.words)}</span>
            <span className="text-muted-foreground">{words.words.toLowerCase()}</span>
          </p>
          {selection ? <p className="mt-1.5 text-xs text-muted-foreground tabular-nums">{fill(words.wholeDocument, { total: fill(isOne(stats.words, locale) ? words.wordsOne : words.wordsOther, { count: n(stats.words) }) })}</p> : null}
        </div>
        {counting ? (
          <span role="status" className="inline-flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground">
            <IconSpinner aria-hidden="true" className="size-3.5" />
            {words.counting}
          </span>
        ) : null}
      </div>

      <dl className="divide-y divide-border border-y border-border">
        <Row term={words.characters}>{n(shown.characters)}</Row>
        <Row term={words.charactersNoSpaces}>{n(shown.charactersNoSpaces)}</Row>
        <Row term={words.sentences}>{n(shown.sentences)}</Row>
        <Row term={words.paragraphs}>{n(shown.paragraphs)}</Row>
      </dl>

      <dl className="-my-1.5">
        <Row term={words.readingTime}>{durationText(minutesFor(shown.words, wordsPerMinute), locale, words.underMinute)}</Row>
        <Row term={words.speakingTime}>{durationText(minutesFor(shown.words, speakingWordsPerMinute), locale, words.underMinute)}</Row>
      </dl>

      {target ? (
        <div className="grid gap-2 border-t border-border pt-4">
          <p className="flex items-center gap-1.5 font-medium tabular-nums">
            {rest <= 0 ? <IconCheck aria-hidden="true" className="size-4 shrink-0" /> : null}
            {goalText}
          </p>
          <Progress value={percent} aria-label={words.goalProgress} className="h-1.5" />
        </div>
      ) : null}
    </div>
  );
}

/**
 * The counting and the words behind DocumentStatsPopover, as plain types and
 * functions: they hold no state and call no hook, so a Server Component can use
 * them too. Counting follows the rules of the locale (where one word ends and
 * the next begins is not the same in English, Thai and Japanese), and a long
 * text is counted a piece at a time while the browser is idle, so typing never
 * waits for it.
 */

/** The numbers of a text. */
export interface DocumentStats {
  /** Words, as the locale's rules separate them. A hyphenated word counts once, as a word counter does. */
  words: number;
  /** Characters as a person sees them: an emoji or a letter with its accent is one. */
  characters: number;
  /** The same without any kind of space. */
  charactersNoSpaces: number;
  /** Sentences, as the locale's rules separate them. */
  sentences: number;
  /** Paragraphs: the lines that have something on them. */
  paragraphs: number;
}

export const NO_STATS: DocumentStats = { words: 0, characters: 0, charactersNoSpaces: 0, sentences: 0, paragraphs: 0 };

/** The goal for the document. */
export interface DocumentGoal {
  /** How many words to write. */
  words: number;
}

/** The words the popover says, for translation. `{count}`, `{goal}`, `{rest}`, `{extra}`, `{selection}` and `{total}` are filled in. */
export interface DocumentStatsLabels {
  /** The name of the panel for screen readers. Default "Document statistics". */
  title?: string;
  /** The button when there is one word. Default "{count} word". */
  wordsOne?: string;
  /** The button for any other number. Default "{count} words". */
  wordsOther?: string;
  /** The button when text is selected. Default "{selection} of {total} words". */
  selectionOf?: string;
  /** The tag that says the numbers are for the whole text. Default "Document". */
  document?: string;
  /** The tag that says the numbers are for what is selected. Default "Selection". */
  selection?: string;
  /** Under the selection's numbers, to keep the whole text in sight. Default "Whole document: {total}". */
  wholeDocument?: string;
  /** Default "Words". */
  words?: string;
  /** Default "Characters". */
  characters?: string;
  /** Default "Characters without spaces". */
  charactersNoSpaces?: string;
  /** Default "Sentences". */
  sentences?: string;
  /** Default "Paragraphs". */
  paragraphs?: string;
  /** Default "Reading time". */
  readingTime?: string;
  /** Default "Speaking time". */
  speakingTime?: string;
  /** Said for a time under a minute. Default "Under 1 min". */
  underMinute?: string;
  /** The goal, with words to go. Default "Goal: {goal} words, {rest} to go". */
  goalToGo?: string;
  /** The goal, reached on the number. Default "Goal reached: {goal} words". */
  goalReached?: string;
  /** The goal, passed. Default "Goal: {goal} words, {extra} over". */
  goalPassed?: string;
  /** The name of the progress bar. Default "Progress towards the goal". */
  goalProgress?: string;
  /** Shown while a long text is being counted. Default "Counting". */
  counting?: string;
}

export const DEFAULT_LABELS = {
  title: "Document statistics",
  wordsOne: "{count} word",
  wordsOther: "{count} words",
  selectionOf: "{selection} of {total} words",
  document: "Document",
  selection: "Selection",
  wholeDocument: "Whole document: {total}",
  words: "Words",
  characters: "Characters",
  charactersNoSpaces: "Characters without spaces",
  sentences: "Sentences",
  paragraphs: "Paragraphs",
  readingTime: "Reading time",
  speakingTime: "Speaking time",
  underMinute: "Under 1 min",
  goalToGo: "Goal: {goal} words, {rest} to go",
  goalReached: "Goal reached: {goal} words",
  goalPassed: "Goal: {goal} words, {extra} over",
  goalProgress: "Progress towards the goal",
  counting: "Counting",
} satisfies Required<DocumentStatsLabels>;

/** Puts values into a template: `fill("{count} words", { count: "412" })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? (values[key] ?? match) : match));
}

/** A number the way the locale writes it. */
export function numberText(value: number, locale: string): string {
  try {
    return new Intl.NumberFormat(locale).format(value);
  } catch {
    return new Intl.NumberFormat("en-US").format(value);
  }
}

/** Whether the locale writes "1 word" with the singular. */
export function isOne(value: number, locale: string): boolean {
  try {
    return new Intl.PluralRules(locale).select(value) === "one";
  } catch {
    return value === 1;
  }
}

type Granularity = "word" | "sentence" | "grapheme";

const segmenters = new Map<string, Intl.Segmenter | null>();

/** A segmenter for the locale, made once. Null where the browser has none: the counts then fall back to simple rules. */
function segmenter(locale: string, granularity: Granularity): Intl.Segmenter | null {
  if (typeof Intl.Segmenter !== "function") return null;
  const key = `${granularity}|${locale}`;
  if (!segmenters.has(key)) {
    let made: Intl.Segmenter | null = null;
    try {
      made = new Intl.Segmenter(locale, { granularity });
    } catch {
      made = new Intl.Segmenter("en-US", { granularity });
    }
    segmenters.set(key, made);
  }
  return segmenters.get(key) ?? null;
}

const HYPHENS = new Set(["-", "‐", "‑"]);

function countWords(text: string, locale: string): number {
  const words = segmenter(locale, "word");
  if (!words) return (text.match(/\S+/g) ?? []).length;
  let count = 0;
  // A hyphen between two words joins them, as it does in a word counter: "well-known" is one.
  let word = false;
  let hyphen = false;
  for (const part of words.segment(text)) {
    if (part.isWordLike) {
      if (!hyphen) count += 1;
      word = true;
      hyphen = false;
    } else {
      hyphen = word && HYPHENS.has(part.segment);
      word = false;
    }
  }
  return count;
}

function countCharacters(text: string, locale: string): { all: number; solid: number } {
  const graphemes = segmenter(locale, "grapheme");
  let all = 0;
  let solid = 0;
  if (graphemes) {
    for (const part of graphemes.segment(text)) {
      all += 1;
      if (/\S/.test(part.segment)) solid += 1;
    }
  } else {
    for (const character of text) {
      all += 1;
      if (/\S/.test(character)) solid += 1;
    }
  }
  return { all, solid };
}

function countSentences(text: string, locale: string): number {
  const sentences = segmenter(locale, "sentence");
  if (!sentences) return (text.match(/[^.!?]*[\p{L}\p{N}][^.!?]*(?:[.!?]+|$)/gu) ?? []).length;
  let count = 0;
  for (const part of sentences.segment(text)) {
    if (/[\p{L}\p{N}]/u.test(part.segment)) count += 1;
  }
  return count;
}

/** The lines that have something on them. Cheap even for a very long text, so it is never split up. */
export function countParagraphs(text: string): number {
  let count = 0;
  for (const line of text.split(/\r?\n/)) if (/\S/.test(line)) count += 1;
  return count;
}

/** All the numbers of a text, at once. Fine for what a page holds; for a book use `countInIdle`. */
export function countText(text: string, locale: string): DocumentStats {
  if (!text) return NO_STATS;
  const characters = countCharacters(text, locale);
  return {
    words: countWords(text, locale),
    characters: characters.all,
    charactersNoSpaces: characters.solid,
    sentences: countSentences(text, locale),
    paragraphs: countParagraphs(text),
  };
}

/** Above this many characters a text is counted in idle time instead of while rendering. */
export const IDLE_ABOVE = 20_000;

/** How much is counted before the browser is asked whether it is still idle. */
const PIECE = 8_000;

/** Cuts a text into pieces of about `size` characters, at a line break or a space, so no word is split in two. */
export function piecesOf(text: string, size: number): string[] {
  const pieces: string[] = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(text.length, start + size);
    if (end < text.length) {
      const line = text.lastIndexOf("\n", end);
      const space = text.lastIndexOf(" ", end);
      if (line > start + size / 2) end = line + 1;
      else if (space > start + size / 2) end = space + 1;
    }
    pieces.push(text.slice(start, end));
    start = end;
  }
  return pieces;
}

interface Idle {
  timeRemaining(): number;
}

/** Runs a task when the browser has nothing better to do, or soon after where there is no such thing (Safari). Returns the way to cancel it. */
function whenIdle(task: (idle: Idle) => void): () => void {
  if (typeof requestIdleCallback === "function") {
    const id = requestIdleCallback(task, { timeout: 600 });
    return () => cancelIdleCallback(id);
  }
  const id = setTimeout(() => task({ timeRemaining: () => 6 }), 16);
  return () => clearTimeout(id);
}

/**
 * Counts a long text a piece at a time, each piece while the browser says it has time to spare, so a key that is pressed
 * in the middle of it is never made to wait. Calls `onDone` with the numbers, or never if it was cancelled first.
 * Returns the way to cancel it; start a new count and cancel the old one whenever the text changes.
 */
export function countInIdle(text: string, locale: string, onDone: (stats: DocumentStats) => void): () => void {
  const pieces = piecesOf(text, PIECE);
  const total = { words: 0, characters: 0, charactersNoSpaces: 0, sentences: 0 };
  let index = 0;
  let cancelled = false;
  let cancelTask: () => void = () => undefined;

  const step = (idle: Idle) => {
    if (cancelled) return;
    do {
      const piece = countText(pieces[index] ?? "", locale);
      total.words += piece.words;
      total.characters += piece.characters;
      total.charactersNoSpaces += piece.charactersNoSpaces;
      total.sentences += piece.sentences;
      index += 1;
    } while (index < pieces.length && idle.timeRemaining() > 4);
    if (index < pieces.length) cancelTask = whenIdle(step);
    else onDone({ ...total, paragraphs: countParagraphs(text) });
  };

  cancelTask = whenIdle(step);
  return () => {
    cancelled = true;
    cancelTask();
  };
}

/** Minutes it takes at a pace, as a fraction. A pace of 0 or less gives 0. */
export function minutesFor(words: number, perMinute: number): number {
  return perMinute > 0 ? words / perMinute : 0;
}

// Intl writes the space before a unit as a no-break or narrow space, and the version of its data decides which: a plain space looks the same and every engine agrees on it.
const ODD_SPACES = new RegExp(`[${String.fromCharCode(0x00a0, 0x2009, 0x202f)}]`, "g");

/** A time for a glance: "2 min", "1 hr 12 min", and under a minute the words you give. Nothing at all gives "0 min". */
export function durationText(minutes: number, locale: string, underMinute: string): string {
  const unit = (value: number, name: "minute" | "hour") => {
    const options = { style: "unit", unit: name, unitDisplay: "short" } as const;
    let text: string;
    try {
      text = new Intl.NumberFormat(locale, options).format(value);
    } catch {
      text = new Intl.NumberFormat("en-US", options).format(value);
    }
    return text.replace(ODD_SPACES, " ");
  };
  if (minutes <= 0) return unit(0, "minute");
  if (minutes < 1) return underMinute;
  const total = Math.round(minutes);
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  if (hours === 0) return unit(total, "minute");
  return rest === 0 ? unit(hours, "hour") : `${unit(hours, "hour")} ${unit(rest, "minute")}`;
}
